/**
 * The operation id a request that never matched a route is grouped under.
 *
 * A request can end before its route is known - a CORS preflight the cors
 * middleware answered, a guard rejection, a 404 - and the transport's URL is
 * all there is to name it by. Sent verbatim, query string and ids included,
 * every distinct URL became a route of its own in the collector's per-route
 * rollups, and a dashboard reads one row per route per bucket: on the Observe
 * API's own telemetry, preflights carrying project ids and range query strings
 * were most of its distinct routes.
 *
 * So a path is cut at its query string and its UUID segments become `:id`.
 * Numeric segments are left alone: the collector folds the same way, and there
 * a parameterless template such as `/reports/2024` is indistinguishable from
 * its URL. Anything that is not a path - the GraphQL agent falls back to the
 * document, which may hold a `?` inside a string literal - is kept as it is.
 *
 * Must stay identical to `foldFallbackOperationId` in the collector
 * (whisprr-api, `telemetry/utils/fallback-operation-id.util.ts`), which folds
 * what older agents still send. A difference splits one route in two for as
 * long as a fleet runs both versions.
 */
export declare function fallbackOperationId(originalUrl: string | undefined): string | undefined;
